arguments.command:
echo "=== Structural validation ===";
grep -c "BEGIN:VCALENDAR" team_meeting.ics | xargs echo "VCALENDAR blocks:";
grep -c "END:VCALENDAR" team_meeting.ics | xargs echo "VCALENDAR ends:";
grep -c "BEGIN:VEVENT" team_meeting.ics | xargs echo "VEVENT blocks:";
grep -c "END:VEVENT" team_meeting.ics | xargs echo "VEVENT ends:";
grep -c "BEGIN:VALARM" team_meeting.ics | xargs echo "VALARM blocks:";
grep -c "END:VALARM" team_meeting.ics | xargs echo "VALARM ends:";
echo "=== Required fields ===";
for field in "VERSION:2.0" "PRODID" "UID" "DTSTAMP" "DTSTART" "DTEND" "SUMMARY"; do
  grep -q "$field" team_meeting.ics && echo "OK: $field" || echo "MISSING: $field";
done;
echo "=== Line ending check (should be CRLF for strict RFC 5545) ===";
file team_meeting.ics
